## CVXPY SOURCE: expressions/constants/constant.py
## Constant -- a constant value in the expression tree

#' Create a Constant Expression
#'
#' Wraps a numeric value as a CVXR constant for use in optimization
#' expressions. Constants are typically created implicitly when combining
#' numeric values with CVXR expressions via arithmetic operators.
#'
#' @param value A numeric scalar, vector, matrix, or sparse matrix.
#' @param name Optional character string name.
#' @returns A \code{Constant} object (inherits from \code{Leaf} and
#'   \code{Expression}).
#'
#' @examples
#' c1 <- Constant(5)
#' c2 <- Constant(matrix(1:6, 2, 3))
#'
#' @export
Constant <- new_class("Constant", parent = Leaf, package = "CVXR",
  properties = list(
    .name   = new_property(class = class_character, default = ""),
    .sparse = new_property(class = class_logical, default = FALSE)
  ),
  constructor = function(value, name = NULL) {
    if (FALSE) new_object(S7_object())  ## S7 static-check guard
    ## Convert and normalize
    sparse <- intf_is_sparse(value)
    value <- intf_convert(value)
    shape <- as.integer(intf_shape(value))

    id <- next_expr_id()

    if (is.null(name)) name <- ""

    obj <- .fast_new(Constant, S7_object(),
      id = as.integer(id),
      .cache = new.env(parent = emptyenv()),
      shape = shape,
      .value = value,
      attributes = list(
        nonneg = FALSE, nonpos = FALSE,
        pos = FALSE, neg = FALSE,
        complex = FALSE, imag = FALSE,
        symmetric = FALSE, diag = FALSE,
        PSD = FALSE, NSD = FALSE,
        hermitian = FALSE, boolean = FALSE,
        integer = FALSE, sparsity = FALSE,
        bounds = NULL
      ),
      ## A Constant is never boolean/integer-constrained (its attributes are
      ## all FALSE above), but constraint 17 requires both properties be named:
      ## `.fast_new` gives an object nothing its constructor omits.
      .sparse_idx  = integer(0),
      .boolean_idx = integer(0),
      .integer_idx = integer(0),
      args = list(),
      .name = name,
      .sparse = sparse
    )
    obj
  }
)

# -- expr_name ---------------------------------------------------------
## CVXPY SOURCE: constant.py lines 96-108

method(expr_name, Constant) <- function(x) {
  if (nchar(x@.name) > 0L) return(x@.name)
  v <- x@.value
  ## is.matrix() is FALSE for a Matrix-package value; the abbreviation applies
  ## to every dimensioned constant (sweep item 4, pass H1).
  if ((is.matrix(v) || inherits(v, "Matrix")) && any(dim(v) > 1L)) {
    ## Abbreviated representation for matrices
    paste0("[", nrow(v), "x", ncol(v), " matrix]")
  } else {
    as.character(v[1L])
  }
}

# -- is_constant: always TRUE -----------------------------------------
## CVXPY SOURCE: constant.py line 115-116

method(is_constant, Constant) <- function(x) TRUE

# -- get_bounds: a constant's bounds are exactly (value, value) --------
## CVXPY SOURCE: constants/constant.py:292-304 (#3080). Needed so bounds
## propagation through e.g. matmul / scaling by a constant treats the constant
## as a point (lb == ub), enabling the exact split formula in matmul_bounds.
method(get_bounds, Constant) <- function(x) {
  v <- x@.value
  ## constant.py:303-304 returns a sparse value as-is, "to avoid memory
  ## blowup"; a Matrix value is already shaped (sweep item 4, pass B).
  if (!inherits(v, "Matrix")) {
    v <- matrix(as.numeric(v), nrow = .shape(x)[1L], ncol = .shape(x)[2L])
  }
  list(v, v)
}

